/* ── Alternatives ─────────────────────────────────────────────────
   A locked span and its replacements. A word turns in place as a drum,
   with the previous and next option faded above and below it; a longer
   span lists its options in the page margin, tied to it by a leader line.
   The option being looked at stands in for the locked words on the page. */
/* Highlight and underline are gradients so the lock can sweep in. */
.twyne-alt-lock,
.twyne-alt-ghost {
  border-radius: 2px;
  background-image:
    linear-gradient(
      color-mix(in srgb, var(--color-cobalt) 11%, transparent),
      color-mix(in srgb, var(--color-cobalt) 11%, transparent)
    ),
    linear-gradient(
      color-mix(in srgb, var(--color-cobalt) 70%, transparent),
      color-mix(in srgb, var(--color-cobalt) 70%, transparent)
    );
  background-repeat: no-repeat;
  background-position:
    0 0,
    0 100%;
  background-size:
    100% 100%,
    100% 1px;
  cursor: ns-resize;
}
.twyne-alt-lock--previewing {
  display: none;
}
.twyne-alt-lock::selection,
.twyne-alt-ghost::selection,
.twyne-alt-ghost *::selection {
  background: transparent;
}
.twyne-alt-ghost {
  background-image:
    linear-gradient(
      color-mix(in srgb, var(--color-cobalt) 17%, transparent),
      color-mix(in srgb, var(--color-cobalt) 17%, transparent)
    ),
    linear-gradient(var(--color-cobalt), var(--color-cobalt));
  background-size:
    100% 100%,
    100% 2px;
}
/* A word's preview is a small slot the next word rolls through. */
.twyne-alt-ghost--word {
  position: relative;
  display: inline-block;
  line-height: 1.3;
  white-space: nowrap;
  text-align: center;
  clip-path: inset(-0.08em -0.06em);
}
.twyne-alt-ghost__in {
  display: inline-block;
}
.twyne-alt-ghost__out {
  position: absolute;
  top: 0;
  left: 50%;
  translate: -50% 0;
  opacity: 0;
  pointer-events: none;
}
/* Just applied: the wording stays inked a moment, then dries. Colour only,
   so it stays on when motion is reduced. */
.twyne-alt-applied {
  border-radius: 2px;
  animation: twyne-alt-dry 900ms ease-out both;
}
@keyframes twyne-alt-dry {
  from {
    background-color: color-mix(in srgb, var(--color-cobalt) 22%, transparent);
    color: var(--color-cobalt);
    box-shadow: inset 0 -2px 0 var(--color-cobalt);
  }
  45% {
    background-color: color-mix(in srgb, var(--color-cobalt) 12%, transparent);
    box-shadow: inset 0 -1px 0
      color-mix(in srgb, var(--color-cobalt) 60%, transparent);
  }
  to {
    background-color: transparent;
    box-shadow: inset 0 -1px 0 transparent;
  }
}

/* Drum: two small labels above and below the locked word. Fixed, so they
   cost the lines around the word a sliver, not a reflow. */
.alt-drum__options {
  position: fixed;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
.alt-drum__above,
.alt-drum__below {
  position: fixed;
  z-index: var(--z-dropdown);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.15rem;
  transform: translateX(-50%);
  pointer-events: none;
}
.alt-drum__below--flip .alt-drum__caption {
  right: calc(100% + 0.35rem);
  left: auto;
}
.alt-drum__pill {
  padding: 0 0.4em;
  border-radius: 3px;
  background: var(--color-paper);
  box-shadow: 0 0 0 1px
    color-mix(in srgb, var(--color-paper-3) 70%, transparent);
  color: var(--color-ink-muted);
  font-family: var(--font-serif);
  font-size: 0.8rem;
  line-height: 1.45;
  white-space: nowrap;
  pointer-events: auto;
  cursor: pointer;
}
.alt-drum__pill:hover {
  color: var(--color-cobalt);
}
/* Beside the next word, not under it, so the drum takes one row below. */
.alt-drum__below {
  min-width: 1px;
  min-height: 1.2rem;
}
.alt-drum__caption {
  position: absolute;
  top: 50%;
  left: calc(100% + 0.35rem);
  transform: translateY(-50%);
  padding: 0.05rem 0.4rem;
  border-radius: 3px;
  background: color-mix(in srgb, var(--color-paper) 92%, transparent);
  color: var(--color-ink-muted);
  font-family: var(--font-typewriter);
  font-size: 0.58rem;
  letter-spacing: 0.03em;
