 319	  const at = state.activeId
 320	    ? options.findIndex((o) => o.id === state.activeId)
 321	    : -1;
 322	  const groupAt = (i: number) => drumGroup(options[i]!);
 323	  let target: number | null = null;
 324	  if (dir > 0) {
 325	    const next = options.findIndex(
 326	      (o, i) => i > at && (at < 0 || drumGroup(o) !== groupAt(at)),
 327	    );
 328	    if (next >= 0) target = next;
 329	  } else if (at > 0) {
 330	    let start = at;
 331	    while (start > 0 && groupAt(start - 1) === groupAt(at)) start--;
 332	    if (start < at) target = start;
 333	    else {
 334	      let prev = start - 1;
 335	      while (prev > 0 && groupAt(prev - 1) === groupAt(start - 1)) prev--;
